858	// isVisible checks if a field/RPC is visible based on the visibility restriction
859	// combined with the `visibility_restriction_selectors`.
860	// Elements with an overlap on `visibility_restriction_selectors` are visible, those without are not visible.
861	// Elements without `google.api.VisibilityRule` annotations entirely are always visible.
862	func isVisible(r *visibility.VisibilityRule, reg *descriptor.Registry) bool {
863		if r == nil {
864			return true
865		}
866	
867		restrictions := strings.Split(strings.TrimSpace(r.Restriction), ",")
868		// No restrictions results in the element always being visible
869		if len(restrictions) == 0 {
870			return true
871		}
872	
873		for _, restriction := range restrictions {
874			if reg.GetVisibilityRestrictionSelectors()[strings.TrimSpace(restriction)] {
875				return true
876			}
877		}
878	
879		return false
880	}
