// isVisible reports whether a proto element carrying the given VisibilityRule
// should be included in the generated output, given the visibility restriction
// selectors configured on the registry.
//
// A nil rule means the element has no `google.api` visibility annotation and is
// therefore always visible. When a rule is present, the element is visible only
// if at least one of its comma-separated restriction labels matches a
// configured selector. This means an annotated element is hidden whenever no
// selectors are configured (an empty selector set matches nothing), while an
// unannotated element always stays visible.
func isVisible(r *visibility.VisibilityRule, reg *descriptor.Registry) bool {
	if r == nil {
		return true
	}

	selectors := reg.GetVisibilityRestrictionSelectors()
	for _, restriction := range strings.Split(r.GetRestriction(), ",") {
		if selectors[strings.TrimSpace(restriction)] {
			return true
		}
	}
	return false
}

// fieldVisibility returns the google.api.field_visibility VisibilityRule set on
// a field, or nil when the field carries no such annotation.
func fieldVisibility(fd *descriptor.Field) *visibility.VisibilityRule {
